package com.example.srchtkt.repository;

import com.example.srchtkt.dto.TicketSearchResponse.TicketRow;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import jakarta.persistence.Query;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Repository;

import java.time.LocalDate;
import java.util.List;

/**
 * Custom JPQL repository that reproduces the seven DB2 cursors
 * declared in the COBOL program (CSR1, CSR10, CSR11, CSR12,
 * CSR100, CSR101, CSR102).
 *
 * <p>The maximum result set per search is 20 rows, mirroring
 * the OCCURS 20 TIMES table in the COBOL COMMAREA.  Pagination
 * is performed at the database level (OFFSET/LIMIT).</p>
 */
@Repository
public class TicketSearchRepository {

    private static final int MAX_ROWS = 20;

    private static final String BASE_SELECT = """
            SELECT new com.example.srchtkt.dto.TicketSearchResponse$TicketRow(
                a.ticketId,
                a.seat,
                b.firstName,
                b.lastName,
                CAST(c.flightDate AS string),
                CAST(c.depTime AS string),
                CAST(c.arrTime AS string),
                c.flightNum,
                c.airportDep,
                c.airportArr
            )
            FROM Ticket a
            JOIN Passenger b ON b.clientId = a.clientId
            JOIN Flight    c ON c.flightId = a.flightId
            """;

    @PersistenceContext
    private EntityManager em;

    // ------------------------------------------------------------------
    // CSR1 – search by ticketId
    // ------------------------------------------------------------------
    /**
     * Fetches up to {@value #MAX_ROWS} ticket rows by ticket ID.
     * Mirrors CSR1 cursor.
     */
    @SuppressWarnings("unchecked")
    public List<TicketRow> findByTicketId(String ticketId) {
        String jpql = BASE_SELECT + "WHERE a.ticketId = :ticketId";
        return em.createQuery(jpql, TicketRow.class)
                 .setParameter("ticketId", ticketId)
                 .setMaxResults(MAX_ROWS)
                 .getResultList();
    }

    // ------------------------------------------------------------------
    // CSR10 – search by clientId only
    // ------------------------------------------------------------------
    /**
     * Fetches up to {@value #MAX_ROWS} ticket rows by client ID.
     * Mirrors CSR10 cursor.
     */
    public List<TicketRow> findByClientId(Long clientId) {
        String jpql = BASE_SELECT + "WHERE b.clientId = :clientId";
        return em.createQuery(jpql, TicketRow.class)
                 .setParameter("clientId", clientId)
                 .setMaxResults(MAX_ROWS)
                 .getResultList();
    }

    // ------------------------------------------------------------------
    // CSR11 – search by clientId + flightNum
    // ------------------------------------------------------------------
    /**
     * Fetches up to {@value #MAX_ROWS} ticket rows by client ID and
     * flight number. Mirrors CSR11 cursor.
     */
    public List<TicketRow> findByClientIdAndFlightNum(Long clientId, String flightNum) {
        String jpql = BASE_SELECT +
                "WHERE b.clientId = :clientId AND c.flightNum = :flightNum";
        return em.createQuery(jpql, TicketRow.class)
                 .setParameter("clientId", clientId)
                 .setParameter("flightNum", flightNum)
                 .setMaxResults(MAX_ROWS)
                 .getResultList();
    }

    // ------------------------------------------------------------------
    // CSR12 – search by clientId + flightDate
    // ------------------------------------------------------------------
    /**
     * Fetches up to {@value #MAX_ROWS} ticket rows by client ID and
     * flight date. Mirrors CSR12 cursor.
     */
    public List<TicketRow> findByClientIdAndDate(Long clientId, LocalDate flightDate) {
        String jpql = BASE_SELECT +
                "WHERE a.clientId = :clientId AND c.flightDate = :flightDate";
        return em.createQuery(jpql, TicketRow.class)
                 .setParameter("clientId", clientId)
                 .setParameter("flightDate", flightDate)
                 .setMaxResults(MAX_ROWS)
                 .getResultList();
    }

    // ------------------------------------------------------------------
    // CSR100 – search by firstName + lastName
    // ------------------------------------------------------------------
    /**
     * Fetches up to {@value #MAX_ROWS} ticket rows by passenger first
     * and last name. Mirrors CSR100 cursor.
     */
    public List<TicketRow> findByName(String firstName, String lastName) {
        String jpql = BASE_SELECT +
                "WHERE b.firstName = :firstName AND b.lastName = :lastName";
        return em.createQuery(jpql, TicketRow.class)
                 .setParameter("firstName", firstName)
                 .setParameter("lastName", lastName)
                 .setMaxResults(MAX_ROWS)
                 .getResultList();
    }

    // ------------------------------------------------------------------
    // CSR101 – search by firstName + lastName + flightNum
    // ------------------------------------------------------------------
    /**
     * Fetches up to {@value #MAX_ROWS} ticket rows by passenger name
     * and flight number. Mirrors CSR101 cursor.
     */
    public List<TicketRow> findByNameAndFlightNum(String firstName,
                                                   String lastName,
                                                   String flightNum) {
        String jpql = BASE_SELECT +
                "WHERE b.firstName = :firstName AND b.lastName = :lastName " +
                "AND c.flightNum = :flightNum";
        return em.createQuery(jpql, TicketRow.class)
                 .setParameter("firstName", firstName)
                 .setParameter("lastName", lastName)
                 .setParameter("flightNum", flightNum)
                 .setMaxResults(MAX_ROWS)
                 .getResultList();
    }

    // ------------------------------------------------------------------
    // CSR102 – search by firstName + lastName + flightDate
    // ------------------------------------------------------------------
    /**
     * Fetches up to {@value #MAX_ROWS} ticket rows by passenger name
     * and flight date. Mirrors CSR102 cursor.
     */
    public List<TicketRow> findByNameAndDate(String firstName,
                                              String lastName,
                                              LocalDate flightDate) {
        String jpql = BASE_SELECT +
                "WHERE b.firstName = :firstName AND b.lastName = :lastName " +
                "AND c.flightDate = :flightDate";
        return em.createQuery(jpql, TicketRow.class)
                 .setParameter("firstName", firstName)
                 .setParameter("lastName", lastName)
                 .setParameter("flightDate", flightDate)
                 .setMaxResults(MAX_ROWS)
                 .getResultList();
    }
}

