// === FILE: src/main/java/com/example/srchtkt/service/SearchStrategy.java ===
package com.example.srchtkt.service;

/**
 * Enum that mirrors the COUNT1 values computed in 0610-CHECK-INSERT.
 *
 * <pre>
 *  COUNT1 =   1 → by TICKETID
 *  COUNT1 =  10 → by CLIENTID only
 *  COUNT1 =  11 → by CLIENTID + FLIGHTNUM
 *  COUNT1 =  12 → by CLIENTID + DATE
 *  COUNT1 = 100 → by FIRSTNAME + LASTNAME
 *  COUNT1 = 101 → by FIRSTNAME + LASTNAME + FLIGHTNUM
 *  COUNT1 = 102 → by FIRSTNAME + LASTNAME + DATE
 *  COUNT1 = 200 → invalid / missing mandatory fields
 * </pre>
 */
public enum SearchStrategy {
    BY_TICKET_ID(1),
    BY_CLIENT_ID(10),
    BY_CLIENT_ID_AND_FLIGHT_NUM(11),
    BY_CLIENT_ID_AND_DATE(12),
    BY_NAME(100),
    BY_NAME_AND_FLIGHT_NUM(101),
    BY_NAME_AND_DATE(102),
    INVALID(200);

    private final int cobolCount;

    SearchStrategy(int cobolCount) {
        this.cobolCount = cobolCount;
    }

    public int getCobolCount() {
        return cobolCount;
    }
}

