package com.example.srchtkt.service;

import org.springframework.stereotype.Service;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;

/**
 * Validates and parses flight date strings.
 *
 * <p>Mirrors paragraph 0640-VERIFY-DATE which checks:
 * <ul>
 *   <li>Year portion (positions 1-4) must be numeric.</li>
 *   <li>Month portion (positions 6-7) must be numeric.</li>
 *   <li>Day portion (positions 9-10) must be numeric.</li>
 *   <li>Separator at position 5 must be '-'.</li>
 *   <li>Separator at position 8 must be '-'.</li>
 * </ul>
 * Expected format: {@code YYYY-MM-DD}.
 * </p>
 */
@Service
public class DateValidationService {

    private static final DateTimeFormatter FORMATTER =
            DateTimeFormatter.ofPattern("yyyy-MM-dd");

    /**
     * Returns {@code true} if the date string is valid (ISO format yyyy-MM-dd).
     *
     * @param dateStr the raw date string supplied by the user
     * @return {@code true} when valid, {@code false} otherwise
     */
    public boolean isValidDate(String dateStr) {
        if (dateStr == null || dateStr.isBlank()) {
            return false;
        }
        // Mirror COBOL checks: positions and separators
        if (dateStr.length() < 10) {
            return false;
        }
        String yearPart  = dateStr.substring(0, 4);
        char   sep1      = dateStr.charAt(4);
        String monthPart = dateStr.substring(5, 7);
        char   sep2      = dateStr.charAt(7);
        String dayPart   = dateStr.substring(8, 10);

        if (!isNumeric(yearPart) || !isNumeric(monthPart) || !isNumeric(dayPart)) {
            return false;
        }
        if (sep1 != '-' || sep2 != '-') {
            return false;
        }
        try {
            LocalDate.parse(dateStr.substring(0, 10), FORMATTER);
            return true;
        } catch (DateTimeParseException e) {
            return false;
        }
    }

    /**
     * Parses a validated date string into a {@link LocalDate}.
     *
     * @param dateStr a date string already confirmed valid by {@link #isValidDate}
     * @return the corresponding {@link LocalDate}
     */
    public LocalDate parse(String dateStr) {
        return LocalDate.parse(dateStr.substring(0, 10), FORMATTER);
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    /**
     * Converts a numeric month index (1-12) to a three-letter month
     * abbreviation, mirroring the WS-DATE-VERIFY-O table in COBOL.
     *
     * @param month 1-based month number
     * @return three-letter abbreviation, e.g. "JAN"
     */
    public String monthAbbreviation(int month) {
        return switch (month) {
            case  1 -> "JAN";
            case  2 -> "FEB";
            case  3 -> "MAR";
            case  4 -> "APR";
            case  5 -> "MAY";
            case  6 -> "JUN";
            case  7 -> "JUL";
            case  8 -> "AUG";
            case  9 -> "SEP";
            case 10 -> "OCT";
            case 11 -> "NOV";
            case 12 -> "DEC";
            default -> "UNK";
        };
    }

    private boolean isNumeric(String s) {
        return s != null && s.chars().allMatch(Character::isDigit);
    }
}

