package com.example.srchtkt.service;

import com.example.srchtkt.dto.TicketSearchRequest;
import com.example.srchtkt.dto.TicketSearchResponse;
import com.example.srchtkt.dto.TicketSearchResponse.TicketRow;
import com.example.srchtkt.repository.TicketSearchRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.Collections;
import java.util.List;

/**
 * Core business-logic service for the SRCHTKT program.
 *
 * <p>Reproduces the following COBOL paragraphs:
 * <ul>
 *   <li>0600-PROCESS-RESEARCH</li>
 *   <li>0610-CHECK-INSERT  – determines {@link SearchStrategy}</li>
 *   <li>0620-DB2-RESEARCH  – dispatches to the correct cursor</li>
 *   <li>0621 … 0628        – individual cursor executions</li>
 *   <li>0630-VERIFY-SQLCODE – handled via empty / non-empty result lists</li>
 * </ul>
 * </p>
 */
@Service
@Transactional(readOnly = true)
public class TicketSearchService {

    private static final String ERR_INVALID_PARAMS =
            "A VALID RESEARCH MUST HAVE AT LEAST: TICKETID OR CLIENTID " +
            "OR CLIENT'S FIRST AND LAST NAME";
    private static final String ERR_INVALID_DATE =
            "WRONG DATE FORMAT, TRY TO INSERT DATE AS YYYY-MM-DD";
    private static final String ERR_NO_DATA =
            "NO DATA MATCH WITH THIS INSERT INFORMATION";

    private final TicketSearchRepository ticketSearchRepository;
    private final DateValidationService  dateValidationService;

    public TicketSearchService(TicketSearchRepository ticketSearchRepository,
                               DateValidationService dateValidationService) {
        this.ticketSearchRepository = ticketSearchRepository;
        this.dateValidationService  = dateValidationService;
    }

    // ------------------------------------------------------------------
    // Public API
    // ------------------------------------------------------------------

    /**
     * Main search entry point.
     *
     * <p>Mirrors MAIN-PARA → 0600-PROCESS-RESEARCH flow when
     * WS-RESEARCH-FLAG = 'Y'.</p>
     *
     * @param request the search criteria supplied by the caller
     * @param page    1-based page number (mirrors WS-F11)
     * @return a fully populated {@link TicketSearchResponse}
     */
    public TicketSearchResponse search(TicketSearchRequest request, int page) {

        // 0610-CHECK-INSERT
        SearchStrategyResult strategyResult = determineStrategy(request);

        if (strategyResult.strategy() == SearchStrategy.INVALID) {
            return new TicketSearchResponse(
                    Collections.emptyList(), page, 0, ERR_INVALID_PARAMS);
        }

        if (strategyResult.dateError()) {
            return new TicketSearchResponse(
                    Collections.emptyList(), page, 0, ERR_INVALID_DATE);
        }

        // 0620-DB2-RESEARCH → 0621..0627
        List<TicketRow> allRows = executeSearch(request, strategyResult.strategy());

        // 0630-VERIFY-SQLCODE: SQLCODE 100 equivalent → empty result
        if (allRows.isEmpty()) {
            return new TicketSearchResponse(
                    Collections.emptyList(), 1, 0, ERR_NO_DATA);
        }

        // Pagination: WS-TABLE-TICKET-R OCCURS 20 / WS-F11 = current page
        int totalPages  = allRows.size();
        int safePageIdx = Math.max(1, Math.min(page, totalPages)) - 1;
        TicketRow row   = allRows.get(safePageIdx);

        return new TicketSearchResponse(
                allRows,
                safePageIdx + 1,
                totalPages,
                null);
    }

    // ------------------------------------------------------------------
    // 0610-CHECK-INSERT
    // ------------------------------------------------------------------

    /**
     * Determines which search strategy to apply based on the filled-in
     * request fields.  Faithfully reproduces the nested IF/ELSE logic
     * of 0610-CHECK-INSERT.
     *
     * <p>Priority order (same as COBOL):
     * <ol>
     *   <li>TICKETID present → BY_TICKET_ID (COUNT1=1)</li>
     *   <li>CLIENTID present, no FLIGHTNUM, no valid DATE → BY_CLIENT_ID (COUNT1=10)</li>
     *   <li>CLIENTID present + FLIGHTNUM → BY_CLIENT_ID_AND_FLIGHT_NUM (COUNT1=11)</li>
     *   <li>CLIENTID present + valid DATE → BY_CLIENT_ID_AND_DATE (COUNT1=12)</li>
     *   <li>FIRSTNAME + LASTNAME, no FLIGHTNUM, no valid DATE → BY_NAME (COUNT1=100)</li>
     *   <li>FIRSTNAME + LASTNAME + FLIGHTNUM → BY_NAME_AND_FLIGHT_NUM (COUNT1=101)</li>
     *   <li>FIRSTNAME + LASTNAME + valid DATE → BY_NAME_AND_DATE (COUNT1=102)</li>
     *   <li>Otherwise → INVALID (COUNT1=200)</li>
     * </ol>
     * </p>
     */
    SearchStrategyResult determineStrategy(TicketSearchRequest req) {

        boolean hasTicketId  = hasValue(req.ticketId());
        boolean hasClientId  = req.clientId() != null;
        boolean hasFirstName = hasValue(req.firstName());
        boolean hasLastName  = hasValue(req.lastName());
        boolean hasFlightNum = hasValue(req.flightNum());
        boolean hasDateStr   = hasValue(req.flightDate());
        boolean dateNumeric  = hasDateStr && isDateNumericPrefix(req.flightDate());
        boolean dateValid    = hasDateStr && dateValidationService.isValidDate(req.flightDate());
        boolean dateError    = false;

        if (hasTicketId) {
            return new SearchStrategyResult(SearchStrategy.BY_TICKET_ID, false);
        }

        if (hasClientId && !hasFlightNum && !dateNumeric) {
            return new SearchStrategyResult(SearchStrategy.BY_CLIENT_ID, false);
        }

        if (hasClientId && hasFlightNum) {
            return new SearchStrategyResult(SearchStrategy.BY_CLIENT_ID_AND_FLIGHT_NUM, false);
        }

        if (hasClientId && dateNumeric) {
            // 0640-VERIFY-DATE
            if (!dateValid) {
                return new SearchStrategyResult(SearchStrategy.BY_CLIENT_ID_AND_DATE, true);
            }
            return new SearchStrategyResult(SearchStrategy.BY_CLIENT_ID_AND_DATE, false);
        }

        if (hasFirstName && hasLastName && !hasFlightNum && !dateNumeric) {
            return new SearchStrategyResult(SearchStrategy.BY_NAME, false);
        }

        if (hasFirstName && hasLastName && hasFlightNum) {
            return new SearchStrategyResult(SearchStrategy.BY_NAME_AND_FLIGHT_NUM, false);
        }

        if (hasFirstName && hasLastName && dateNumeric) {
            // 0640-VERIFY-DATE
            if (!dateValid) {
                return new SearchStrategyResult(SearchStrategy.BY_NAME_AND_DATE, true);
            }
            return new SearchStrategyResult(SearchStrategy.BY_NAME_AND_DATE, false);
        }

        return new SearchStrategyResult(SearchStrategy.INVALID, false);
    }

    // ------------------------------------------------------------------
    // 0620-DB2-RESEARCH dispatch
    // ------------------------------------------------------------------

    /**
     * Dispatches to the appropriate repository method based on the
     * determined strategy. Mirrors 0620-DB2-RESEARCH EVALUATE block.
     */
    private List<TicketRow> executeSearch(TicketSearchRequest req,
                                          SearchStrategy strategy) {
        return switch (strategy) {
            case BY_TICKET_ID ->
                    // 0621-DB2-CSR1
                    ticketSearchRepository.findByTicketId(
                            req.ticketId().trim());

            case BY_CLIENT_ID ->
                    // 0622-DB2-CSR10
                    ticketSearchRepository.findByClientId(
                            req.clientId());

            case BY_CLIENT_ID_AND_FLIGHT_NUM ->
                    // 0623-DB2-CSR11
                    ticketSearchRepository.findByClientIdAndFlightNum(
                            req.clientId(),
                            req.flightNum().trim());

            case BY_CLIENT_ID_AND_DATE ->
                    // 0624-DB2-CSR12
                    ticketSearchRepository.findByClientIdAndDate(
                            req.clientId(),
                            dateValidationService.parse(req.flightDate()));

            case BY_NAME ->
                    // 0625-DB2-CSR100
                    ticketSearchRepository.findByName(
                            req.firstName().trim(),
                            req.lastName().trim());

            case BY_NAME_AND_FLIGHT_NUM ->
                    // 0626-DB2-CSR101
                    ticketSearchRepository.findByNameAndFlightNum(
                            req.firstName().trim(),
                            req.lastName().trim(),
                            req.flightNum().trim());

            case BY_NAME_AND_DATE ->
                    // 0627-DB2-CSR102
                    ticketSearchRepository.findByNameAndDate(
                            req.firstName().trim(),
                            req.lastName().trim(),
                            dateValidationService.parse(req.flightDate()));

            // 0628-INCORRECT — handled before this method is called
            case INVALID -> Collections.emptyList();
        };
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private boolean hasValue(String s) {
        return s != null && !s.isBlank();
    }

    /**
     * Returns true if the first four characters of the date string are
     * numeric, mirroring FDATEI(1:4) IS NUMERIC check in COBOL.
     */
    private boolean isDateNumericPrefix(String dateStr) {
        if (dateStr == null || dateStr.length() < 4) return false;
        return dateStr.substring(0, 4).chars().allMatch(Character::isDigit);
    }

    // ------------------------------------------------------------------
    // Inner result record
    // ------------------------------------------------------------------

    /**
     * Carries both the resolved strategy and a flag indicating a date
     * validation error (mirrors WS-FLAG-DATE).
     */
    record SearchStrategyResult(SearchStrategy strategy, boolean dateError) {}
}

