package com.example.srchtkt.service;

import com.example.srchtkt.dto.PrintTicketRequest;
import com.example.srchtkt.dto.PrintTicketResponse;
import com.example.srchtkt.repository.AirportRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Reproduces the print-ticket logic from paragraphs
 * 0511-CALL-INTRDR and 0512-MOVE-VARIABLES.
 *
 * <p>In the original COBOL, this built a JCL spool job via
 * CICS SPOOLOPEN/SPOOLWRITE/SPOOLCLOSE to submit a batch print.
 * In this Spring Boot port the equivalent action is to assemble
 * the printable ticket data and return it to the caller, which
 * can then route it to whichever print / PDF service is available
 * in the target environment.</p>
 */
@Service
@Transactional(readOnly = true)
public class PrintTicketService {

    private static final String[] MONTH_ABBR = {
        "", "JAN", "FEB", "MAR", "APR", "MAY", "JUN",
        "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"
    };

    private final AirportRepository airportRepository;
    private final DateValidationService dateValidationService;

    public PrintTicketService(AirportRepository airportRepository,
                              DateValidationService dateValidationService) {
        this.airportRepository  = airportRepository;
        this.dateValidationService = dateValidationService;
    }

    /**
     * Assembles a human-readable ticket document string.
     *
     * <p>Mirrors 0512-MOVE-VARIABLES:
     * <ul>
     *   <li>Builds WS-FULLNAME  (firstname + ' ' + lastname)</li>
     *   <li>Resolves departure city from AIRPORT table (WS-DEPCITY)</li>
     *   <li>Resolves arrival   city from AIRPORT table (WS-ARRCITY)</li>
     *   <li>Builds WS-FULLCITY1 (city-IATA)</li>
     *   <li>Builds WS-FULLCITY2 (city-IATA)</li>
     *   <li>Converts flightDate YYYY-MM-DD → DD-MMM-YYYY (WS-DATEFULL)</li>
     * </ul>
     * </p>
     *
     * @param req ticket data for printing
     * @return assembled ticket text or an error message
     */
    public PrintTicketResponse print(PrintTicketRequest req) {
        try {
            // WS-FULLNAME
            String fullName = (req.firstName().trim() + " " + req.lastName().trim()).trim();

            // Resolve departure city
            String depCity = airportRepository
                    .findCityByAirportId(req.airportDep().trim())
                    .orElse("UNKNOWN");

            // Resolve arrival city
            String arrCity = airportRepository
                    .findCityByAirportId(req.airportArr().trim())
                    .orElse("UNKNOWN");

            // WS-FULLCITY1 / WS-FULLCITY2
            String fullCity1 = depCity.trim() + "-" + req.airportDep().trim();
            String fullCity2 = arrCity.trim() + "-" + req.airportArr().trim();

            // WS-DATEFULL: YYYY-MM-DD  → DD-MMM-YYYY
            // mirrors: day (pos 9:2), monthAbbr (pos 6:2 as int), year (pos 1:4)
            String dateFull = buildDateFull(req.flightDate());

            // Assemble printable ticket (mirrors JCL SYSIN lines)
            String ticket = buildTicketDocument(
                    fullName, req.seat(), req.flightNum(),
                    req.airportDep(), req.airportArr(),
                    req.flightDate(), req.depTime(),
                    dateFull, fullCity1, fullCity2);

            return new PrintTicketResponse(true,
                    "TICKET SUCCESSFULLY PRINTED\n" + ticket);

        } catch (Exception ex) {
            return new PrintTicketResponse(false,
                    "ERROR IN THE PRINT PROCESS: " + ex.getMessage());
        }
    }

    // ------------------------------------------------------------------
    // 0512-MOVE-VARIABLES helpers
    // ------------------------------------------------------------------

    /**
     * Converts {@code YYYY-MM-DD} to {@code DD-MMM-YYYY}.
     * Mirrors the date-formatting logic in 0512-MOVE-VARIABLES.
     */
    private String buildDateFull(String isoDate) {
        if (isoDate == null || isoDate.length() < 10) return isoDate;
        String year  = isoDate.substring(0, 4);   // WS-FDATE(1:4)
        int    month = Integer.parseInt(isoDate.substring(5, 7)); // pos 6:2
        String day   = isoDate.substring(8, 10);  // WS-FDATE(9:2)
        String mon   = MONTH_ABBR[month];          // WS-DATE-VERIFY(WS-DATE-TEST)
        return day + mon + year;                   // WS-DATEFULL
    }

    /**
     * Builds the ticket text block that would have been spooled via
     * CICS SPOOLWRITE in the original COBOL.
     */
    private String buildTicketDocument(String fullName, String seat,
                                        String flightNum,
                                        String airportDep, String airportArr,
                                        String flightDate, String depTime,
                                        String dateFull,
                                        String fullCity1, String fullCity2) {
        return """
               ========================================
               AIRLINE TICKET
               ========================================
               PASSENGER : %s
               SEAT      : %s
               FLIGHT    : %s
               DEPARTURE : %s  (%s)
               ARRIVAL   : %s
               DATE      : %s  [%s]
               DEP TIME  : %s
               ========================================
               """.formatted(
                fullName, seat, flightNum,
                fullCity1, airportDep,
                fullCity2,
                flightDate, dateFull,
                depTime);
    }
}

