package com.example.srchtkt.controller;

import com.example.srchtkt.dto.PrintTicketRequest;
import com.example.srchtkt.dto.PrintTicketResponse;
import com.example.srchtkt.dto.TicketSearchRequest;
import com.example.srchtkt.dto.TicketSearchResponse;
import com.example.srchtkt.service.PrintTicketService;
import com.example.srchtkt.service.TicketSearchService;
import jakarta.validation.Valid;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

/**
 * REST controller exposing the SRCHTKT search and print operations.
 *
 * <p>Maps the CICS pseudo-conversational map interaction to stateless
 * HTTP endpoints:
 * <ul>
 *   <li>{@code POST /api/tickets/search}  – mirrors the ENTER key / research flow</li>
 *   <li>{@code POST /api/tickets/print}   – mirrors DFHPF12 / 0511-CALL-INTRDR</li>
 * </ul>
 * Pagination (PF10/PF11) is handled by the {@code page} query parameter.
 * </p>
 */
@RestController
@RequestMapping("/api/tickets")
public class TicketSearchController {

    private final TicketSearchService ticketSearchService;
    private final PrintTicketService  printTicketService;

    public TicketSearchController(TicketSearchService ticketSearchService,
                                   PrintTicketService printTicketService) {
        this.ticketSearchService = ticketSearchService;
        this.printTicketService  = printTicketService;
    }

    /**
     * Searches for tickets according to the criteria provided.
     *
     * <p>Mirrors the ENTER key press path in MAIN-PARA when
     * WS-RESEARCH-FLAG = 'Y', driving 0600-PROCESS-RESEARCH.
     * The {@code page} parameter reproduces PF10/PF11 navigation.</p>
     *
     * @param request search criteria (maps to CICS map input fields)
     * @param page    1-based page index (default 1, mirrors WS-F11)
     * @return a {@link TicketSearchResponse} with matching tickets
     */
    @PostMapping("/search")
    public ResponseEntity<TicketSearchResponse> search(
            @RequestBody @Valid TicketSearchRequest request,
            @RequestParam(defaultValue = "1") int page) {

        if (page < 1) page = 1;
        TicketSearchResponse response = ticketSearchService.search(request, page);
        return ResponseEntity.ok(response);
    }

    /**
     * Assembles and returns printable ticket data.
     *
     * <p>Mirrors DFHPF12 → 0511-CALL-INTRDR → 0512-MOVE-VARIABLES.
     * The CICS SPOOLOPEN/SPOOLWRITE/SPOOLCLOSE logic is replaced by
     * returning a structured response that the client can route to
     * a printer or PDF generator.</p>
     *
     * @param request ticket data to be printed
     * @return print result with assembled ticket text
     */
    @PostMapping("/print")
    public ResponseEntity<PrintTicketResponse> print(
            @RequestBody @Valid PrintTicketRequest request) {

        PrintTicketResponse response = printTicketService.print(request);
        if (response.success()) {
            return ResponseEntity.ok(response);
        }
        return ResponseEntity.internalServerError().body(response);
    }
}

