package com.example.srchtkt.config;

import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.net.URI;
import java.time.Instant;

/**
 * Global exception handler.
 *
 * <p>Mirrors the COBOL 0630-VERIFY-SQLCODE "WHEN OTHER" branch that
 * moves a communication-error message to the map output fields.</p>
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    /**
     * Handles bean-validation failures (e.g. malformed request bodies).
     */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ProblemDetail handleValidation(MethodArgumentNotValidException ex) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(
                HttpStatus.BAD_REQUEST,
                "Request validation failed");
        pd.setType(URI.create("urn:srchtkt:error:validation"));
        pd.setProperty("timestamp", Instant.now());
        pd.setProperty("errors",
                ex.getBindingResult().getFieldErrors().stream()
                  .map(fe -> fe.getField() + ": " + fe.getDefaultMessage())
                  .toList());
        return pd;
    }

    /**
     * Handles any unexpected runtime error.
     * Mirrors: "COMMUNICATION ERROR BETWEEN SYSTEM AND DB, CALL IT DEPT".
     */
    @ExceptionHandler(Exception.class)
    public ProblemDetail handleGeneral(Exception ex) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(
                HttpStatus.INTERNAL_SERVER_ERROR,
                "COMMUNICATION ERROR BETWEEN SYSTEM AND DB, CALL IT DEPT");
        pd.setType(URI.create("urn:srchtkt:error:system"));
        pd.setProperty("timestamp", Instant.now());
        pd.setProperty("detail", ex.getMessage());
        return pd;
    }
}
